  "Text to rewrite": "ข้อความที่จะเขียนใหม่",
  "Paste AI-generated or stiff text — it comes back sounding like a person wrote it.": "วางข้อความที่ AI สร้างหรือข้อความแข็งๆ แล้วจะได้กลับมาเหมือนคนเขียน",
