  "Keeps your meaning and facts exactly — changes only how it reads. The writing sample is optional but makes the biggest difference.": "คงความหมายและข้อเท็จจริงไว้ทุกอย่าง เปลี่ยนแค่สำนวน ตัวอย่างงานเขียนไม่บังคับ แต่ช่วยได้มากที่สุด",
  "Rewritten": "เขียนใหม่แล้ว",
  "Paste stiff or AI-sounding text, add a sample of your own writing, and it comes back in your voice — same meaning, human rhythm.": "วางข้อความแข็งๆ หรือที่ฟังเหมือน AI เพิ่มตัวอย่างงานเขียนของคุณ แล้วจะได้กลับมาเป็นสำนวนของคุณ ความหมายเดิม จังหวะแบบมนุษย์",
  "Chat through Attune — it reads the whole conversation and sharpens every next prompt.": "แชทผ่าน Attune จะอ่านบทสนทนาทั้งหมดและทำให้พรอมต์ถัดไปคมขึ้นทุกครั้ง",
  "What do you want out of this whole conversation? (optional, but it makes every prompt better)": "ต้องการอะไรจากบทสนทนานี้ทั้งหมด (ไม่บังคับ แต่ทำให้ทุกพรอมต์ดีขึ้น)",
  "Bring the chat from {t} — paste the whole conversation or just its last reply:": "นำแชทจาก {t} มา วางบทสนทนาทั้งหมดหรือแค่คำตอบล่าสุด:",
  "Paste here…": "วางที่นี่…",
  "Read it & suggest my reply": "อ่านแล้วแนะนำคำตอบให้ฉัน",
  "What do you want to ask? Type it however you like.": "อยากถามอะไร พิมพ์ได้ตามสบาย",
  "Optimize my prompt": "ปรับพรอมต์ของฉัน",
  "The loop: type intent → get an optimized prompt → send it → bring the reply back → each next prompt is sharper. In the phone app, the share-sheet replaces copy-paste entirely.": "วงจร: พิมพ์ความต้องการ → ได้พรอมต์ที่ปรับแล้ว → ส่ง → นำคำตอบกลับมา → พรอมต์ถัดไปจะคมขึ้น ในแอปโทรศัพท์ เมนูแชร์ใช้แทนการคัดลอกวางได้เลย",
