  "Too heavy for a phone — it can close the app. Core or Blaze run smoothly here; this one is in the desktop app.": "หนักเกินไปสำหรับโทรศัพท์ อาจทำให้แอปปิดตัว Core หรือ Blaze ทำงานลื่นที่นี่ ตัวนี้อยู่ในแอปเดสก์ท็อป",
