  "per company system, once": "ต่อระบบบริษัท จ่ายครั้งเดียว",
  "Pro is bought in the Google Play version of Attune — one tap, paid by card or from your Vodafone / Orange / Etisalat balance, and it switches on by itself.": "ซื้อ Pro ได้ใน Attune เวอร์ชัน Google Play — แตะครั้งเดียว จ่ายด้วยบัตรหรือยอดเงิน Vodafone / Orange / Etisalat แล้วจะเปิดใช้เอง",
  "Cancel any time in Google Play → Subscriptions. The plan renews by itself; nothing to send, nobody to message.": "ยกเลิกได้ทุกเมื่อที่ Google Play → การสมัครใช้บริการ แผนจะต่ออายุเอง ไม่ต้องส่งอะไรหรือทักใคร",
