  "Installed weights never update on their own, so a prompt that works today works the same way in a year. The fingerprint proves exactly which file is answering.": "น้ำหนักโมเดลที่ติดตั้งแล้วจะไม่อัปเดตเอง ดังนั้นพรอมป์ที่ใช้ได้วันนี้ก็จะให้ผลเหมือนเดิมในอีกหนึ่งปี ลายนิ้วมือพิสูจน์ได้ว่าไฟล์ไหนกำลังตอบอยู่",
