  "e.g. I run a small shop in Egypt. Answer in Egyptian Arabic unless I write in English. Give prices in EGP.": "เช่น ฉันเปิดร้านเล็ก ๆ ในอียิปต์ ตอบเป็นภาษาอาหรับอียิปต์ ยกเว้นเมื่อฉันเขียนเป็นภาษาอังกฤษ ให้ราคาเป็น EGP",
  "Saved when you tap outside the box. Stays on this phone.": "บันทึกเมื่อคุณแตะนอกกล่อง และเก็บไว้ในโทรศัพท์เครื่องนี้เท่านั้น",
  "Web lookup": "ค้นหาบนเว็บ",
