  "Prefill runs where compute is fastest, decode where bandwidth is. Using both raises usable bandwidth ~43 → 59 GB/s.": "Prefill ทำงานบนส่วนที่ประมวลผลเร็วที่สุด ส่วน decode ทำงานบนส่วนที่แบนด์วิดท์สูงที่สุด การใช้ทั้งสองช่วยเพิ่มแบนด์วิดท์ที่ใช้ได้จริงจาก ~43 เป็น 59 GB/s",
