  "This is added to every field document — and it's also what your own adapter trains on, so the model learns your operation, not a generic one.": "ข้อความนี้จะถูกเพิ่มในเอกสารภาคสนามทุกฉบับ และเป็นข้อมูลที่อะแดปเตอร์ของคุณใช้ฝึกด้วย โมเดลจึงเรียนรู้งานของคุณ ไม่ใช่งานทั่วไป",
