  "Unlocked. How should it be restored?": "ปลดล็อกแล้ว ต้องการกู้คืนแบบไหน",
  "Replace everything on this phone": "แทนที่ทุกอย่างในโทรศัพท์เครื่องนี้",
  "This phone becomes exactly like the backup.": "โทรศัพท์เครื่องนี้จะเหมือนกับข้อมูลสำรองทุกอย่าง",
  "Merge": "รวม",
  "Keep everything on this phone and add the backup's chats, memory, reminders and cycle days. The Money ledger is only taken from the backup if this phone has none.": "เก็บทุกอย่างในโทรศัพท์เครื่องนี้ไว้ แล้วเพิ่มแชต ความจำ การแจ้งเตือน และวันรอบเดือนจากข้อมูลสำรอง บัญชีการเงินจะถูกนำมาจากข้อมูลสำรองก็ต่อเมื่อโทรศัพท์เครื่องนี้ยังไม่มี",
  "This phone's {c} chats and {l} ledger entries will be replaced by the backup's. You can undo this once, right after.": "แชต {c} รายการและรายการบัญชี {l} รายการในโทรศัพท์เครื่องนี้จะถูกแทนที่ด้วยข้อมูลจากข้อมูลสำรอง คุณเลิกทำได้หนึ่งครั้งทันทีหลังจากนั้น",
  "The backup's items will be added to this phone. You can undo this once, right after.": "รายการจากข้อมูลสำรองจะถูกเพิ่มเข้าโทรศัพท์เครื่องนี้ คุณเลิกทำได้หนึ่งครั้งทันทีหลังจากนั้น",
  "Yes, restore": "ใช่ กู้คืนเลย",
  "Undo the last restore": "เลิกทำการกู้คืนครั้งล่าสุด",
