  "Loading the model…": "กำลังโหลดโมเดล…",
  "Nothing in the app can reach the internet — no web lookup, no maps, no downloads. The model and everything on the phone keep working.": "ไม่มีอะไรในแอปเข้าถึงอินเทอร์เน็ตได้ — ไม่มีการค้นเว็บ แผนที่ หรือการดาวน์โหลด โมเดลและทุกอย่างในโทรศัพท์ยังใช้งานได้",
  "The model reasons first on every question. Clearly better on hard problems, but on a phone the answer starts 30–90 s later. Off: tap “Think” on just the questions that need it.": "โมเดลจะให้เหตุผลก่อนทุกคำถาม ดีกว่าชัดเจนกับปัญหายาก แต่บนโทรศัพท์คำตอบจะเริ่มช้าลง 30–90 วินาที เมื่อปิด: แตะ “คิด” เฉพาะคำถามที่ต้องการ",
  "The same model as below, given the memory to hold a whole book of context at once. On a 48 GB machine the spare RAM is better spent on context than on precision — you can hand it an entire contract or a year of notes and it keeps all of it in view.": "โมเดลเดียวกับด้านล่าง แต่มีหน่วยความจำพอเก็บบริบทได้ทั้งเล่ม บนเครื่อง 48 GB RAM ที่เหลือคุ้มกว่าถ้าใช้กับบริบทมากกว่าความละเอียด — ใส่สัญญาทั้งฉบับหรือบันทึกทั้งปีได้ และมันเห็นครบทั้งหมด",
  "The whole assistant, on your device": "ผู้ช่วยเต็มรูปแบบ ในอุปกรณ์ของคุณ",
  "Works entirely offline. No account, ever.": "ทำงานแบบออฟไลน์ทั้งหมด ไม่ต้องมีบัญชีเลย",
