  "Message": "ข้อความ",
  "No number — WhatsApp will open its contact list with the message ready.": "ไม่มีหมายเลข — WhatsApp จะเปิดรายชื่อผู้ติดต่อพร้อมข้อความที่เตรียมไว้",
  "Set reminder": "ตั้งการเตือน",
