  "Notifications are off for Attune — tap to allow them, or reminders can't appear.": "การแจ้งเตือนของ Attune ปิดอยู่ — แตะเพื่ออนุญาต ไม่เช่นนั้นการเตือนจะไม่ปรากฏ",
  "Reminders may come up to 10 minutes late. Tap to allow “Alarms & reminders” for Attune so they ring on the minute.": "การเตือนอาจมาช้าได้ถึง 10 นาที แตะเพื่ออนุญาต “การปลุกและการเตือน” ให้ Attune เพื่อให้เตือนตรงเวลา",
  "In the browser reminders are only listed — the Android app rings them.": "ในเบราว์เซอร์จะแสดงการเตือนเป็นรายการเท่านั้น แอป Android จะเป็นฝ่ายส่งเสียงเตือน",
  "from a promise": "จากคำสัญญา",
