  "Could not open it": "เปิดไม่ได้",
  "No app on this phone can do that.": "ไม่มีแอปในโทรศัพท์เครื่องนี้ที่ทำสิ่งนั้นได้",
  "WhatsApp isn't installed — opened the share sheet instead.": "ไม่ได้ติดตั้ง WhatsApp — เปิดเมนูแชร์แทน",
  "Unknown action": "การดำเนินการที่ไม่รู้จัก",
